"""Writes every topic's generated files from its tool functions and the prose in `scaffold_content.py`.

    python scaffold.py                    # every topic
    python scaffold.py supervised.ranking # one topic
    python scaffold.py console            # console/agentic_configurations.yaml: the console agents plus every topic's agents and tools
    python scaffold.py --check            # write nothing; exit 1 if any generated file is stale

For each `<category>/<topic>/` it writes:

    agentic_configuration.yaml   llms, the two agents, every tool with its description and arguments,
                                 the orchestrator and the pipeline — the tool block is read off the
                                 functions in `tools/`, not typed
    prompt.md                    the worker agent's prompt, with the tool catalogue embedded
    decider_prompt.md            the decider agent's prompt
    agents.py / decider.py       named handles onto the two agents
    tools/catalogue.py           `<slug>_catalogue_tool`, the runtime view of the same list

`console/agentic_configurations.yaml` is derived from all of those (see `scaffold_console.py`): one file holding the console's agents and
every topic's tools, decider and worker, which is what the console actually runs.

The tools themselves (`tools/*.py`) and the prose (`scaffold_content.py`) are the only things written by
hand; everything else is derived, so adding a function to a tools module and re-running this is all it
takes for the agents to know about it.
"""

from __future__ import annotations

import re
import sys
from pathlib import Path

from ml_core.specs import ToolInfo, discover_tools, render_tool_catalogue, render_tools_yaml
from scaffold_content import TOPICS

ROOT = Path(__file__).resolve().parent

# Named for the topic's own use, not `generator_llm_thinker*`: `agent_builder` keeps every parsed config in class-level dictionaries, so a
# name shared with `console/agentic_configurations.yaml` would let whichever file loads last overwrite the other's model settings.
LLMS = '''llms:
  # Ceilings: a sub agent's decider writes one JSON plan (about 1k tokens) and its worker a short report, so a small model that fails to stop is cut
  # off at 3000 / 6000 tokens, not 16000 (about 19 minutes of repeating itself).
  topic_worker_llm:  # the workhorse behind the worker agent, and the decider's fallback
    model: "hf_local/Caglana/qwen0.5b-tinylora-ds-assistant"
    api_key: "HF_TOKEN"
    max_tokens: 6000
    type: "generator"
  topic_decider_llm:  # the decider's own model, and the worker's fallback
    model: "hf_local/Caglana/qwen0.5b-tinylora-ds-assistant"
    api_key: "HF_TOKEN"
    max_tokens: 3000
    type: "generator"
'''

YAML_HEADER = """# {title} — agents, tools and pipeline.
#
# Generated by `python scaffold.py {key}` from the functions in `tools/` and the prose in
# `scaffold_content.py`. Edit those and re-run it rather than editing this file: the `tools:` block below
# is read off the function signatures and docstrings, so it cannot drift from what the code does.
#
#   {decider}   reads the problem and the data, runs the read-only checks in `tools/diagnostics.py`, and
#       decides which approach and which tools fit — it never fits anything.
#   {worker}    carries that decision out with every tool below, and reports what it measured.
#
# The console runs copies of these two agents from `console/agentic_configurations.yaml` (built from this file by
# `python scaffold.py console`), once `ml_decider_agent` has chosen this topic; `console/orchestrate.py` runs them in
# that order. This file is what the topic's own handles (`agents.py`, `decider.py`) and `cli.py tools` read.
"""

DECIDER_TEMPLATE = '''"""The decider for {title}: `{decider}` in `agentic_configuration.yaml`.

It reads the problem statement and the data, runs the read-only checks in `tools/diagnostics.py`, and
answers one question — *which approach, with which tools, and why* — as a JSON object the worker agent
(`agents.py`) then executes. It never fits a model or changes data.

    from {key}.decider import DECIDER

    plan = DECIDER.run(question="...", context="Current data path: data.csv")
"""

from __future__ import annotations

from pathlib import Path

from ml_core.handles import AgentHandle

CONFIG_DIR = Path(__file__).resolve().parent


class {cls}Decider(AgentHandle):
    """`{decider}` — chooses the approach for {title} and names the tools to run."""

    NAME = "{decider}"
    CONFIG_DIR = CONFIG_DIR


DECIDER = {cls}Decider
'''

AGENTS_TEMPLATE = '''"""The worker for {title}: `{worker}` in `agentic_configuration.yaml`.

It has every tool in `tools/` and runs after the decider (`decider.py`), reading the decider's plan as
`{{agent_output}}`. Run together, in order, they are this topic's workflow:

    from {key}.decider import DECIDER
    from {key}.agents import AGENT

    plan = DECIDER.run(question=question, context=context)
    result = AGENT.run(question=question, context=context, agent_outputs={{DECIDER.NAME: plan}})

`console/orchestrate.py` does exactly that, and also handles the human approval step in between.
"""

from __future__ import annotations

from pathlib import Path

from ml_core.handles import AgentHandle

CONFIG_DIR = Path(__file__).resolve().parent
WORKFLOW = ("{decider}", "{worker}")


class {cls}Agent(AgentHandle):
    """`{worker}` — solves {title} problems with the tools in `tools/`."""

    NAME = "{worker}"
    CONFIG_DIR = CONFIG_DIR


AGENT = {cls}Agent
'''

CATALOGUE_TEMPLATE = '''"""The runtime catalogue of this topic's tools."""

from __future__ import annotations

from ml_core.catalogue import list_tools
from ml_core.tooling import tool


@tool
def tool_catalogue(group: str | None = None) -> dict:
    """List every tool available for {title} with its description, arguments and optional dependencies — call it to check whether a tool exists for a step before improvising one.

    Args:
        group: Restrict the listing to one tool module, e.g. "models" or "evaluation".
    """
    return list_tools("{key}", group)
'''


def link_tools(text: str, tools: list[ToolInfo]) -> str:
    """Rewrite a backticked tool function name (`fit_random_forest`) as the name the agent actually calls (`fit_random_forest_tool`), so
    prose written by hand and descriptions copied from docstrings can never name a tool the plan validator would reject."""
    names = {t.name: t.tool_name for t in tools}
    return re.sub(r"`(\w+)`", lambda m: f"`{names[m.group(1)]}`" if m.group(1) in names else m.group(0), text)


def bullets(items: list[str]) -> str:
    return "\n".join(f"- {item}" for item in items)


def numbered(items: list[str]) -> str:
    return "\n".join(f"{i}. {item}" for i, item in enumerate(items, start=1))


def choose_table(content: dict, tools: list[ToolInfo]) -> str:
    known = {t.name: t for t in tools}
    rows = []
    for situation, names in content["choose"]:
        missing = [n for n in names if n not in known]
        if missing:
            raise ValueError(f"{content['key']}: `choose` names tools that do not exist: {missing}")
        rows.append(f"- **{situation}** — " + ", ".join(f"`{known[n].tool_name}`" for n in names))
    return "\n".join(rows)


def render_worker_prompt(content: dict, tools: list[ToolInfo]) -> str:
    return f"""You are a data scientist working on a {content['title']} problem. {content['role']}
You do not decide whether this is the right kind of problem — an earlier stage already did — and you do
not invent results: everything you report is something a tool returned.

## The request

{{question}}

## What is known about the data

{{context}}

## What the agents before you produced

{{agent_output}}

Read the plan above first. It names the approach the decider chose and the tools it expects you to run,
with the arguments it settled on. Follow it; deviate only when a tool's output shows the plan was wrong,
and say so when you do.

## Your tools

Almost every tool takes `data`, and it is never optional in practice — a call without it reads nothing
and fails. Take it from the `Current data path:` line in `{{context}}`; quote it exactly, do not
paraphrase it or invent one. Where that line is empty, that is a reason to escalate, not to call a tool
with nothing. `target` (and the other column arguments) must be a column name that really exists in the
data — if a tool answers that a column is missing, read the column list it returns and correct the call.

A tool answers `{{"status": "ok", ...}}` or `{{"status": "error", "message": ...}}`. An error is
information, not a stopping point: read it, fix the arguments, call again. A tool that answers with an
`install` field needs an optional package this environment lacks — name it, and pick another tool.
`{content['slug']}_catalogue_tool` lists everything below with every argument, if you need the exact signature.

{render_tool_catalogue(tools)}

## How to choose

{choose_table(content, tools)}

## What to do

{numbered(content['workflow'])}

## Judging the result

{content['judging']}

## What to produce

{bullets(content['produce'])}

## Rules

{bullets(content['rules'] + COMMON_RULES)}
"""


COMMON_RULES = [
    "Quote what the tools returned. A score, a count or a column name that you did not read out of a tool result is a claim, not a result.",
    "Report a failed or skipped tool as failed or skipped — never fill the gap with what the result would probably have been.",
    "One change at a time. If two things changed between two runs, you do not know which one moved the number.",
    "Escalate rather than guess when the data path, the target or the problem itself is missing or contradictory: say what is needed and stop.",
]


def render_decider_prompt(content: dict, tools: list[ToolInfo]) -> str:
    diagnostics = [t for t in tools if t.diagnostic]
    return f"""You are the decider for {content['title']} problems. {content['role']}
Your job is to look at this problem and this data and decide *how* it should be solved — which approach,
which tools, in what order, with which settings — before anything is fitted. You do not fit models or
change data; a worker agent carries out your plan with the full toolbox.

## The request

{{question}}

## What is known about the data

{{context}}

## What the agents before you produced

{{agent_output}}

## Is this the right topic?

{bullets(content['fits'])}

If the problem is really one of these instead, say so in `escalation` and stop:

{bullets(content['not_this'])}

## Your tools

You may run only the read-only checks below, and `{content['slug']}_catalogue_tool` to see what the worker can do.
Take `data` from the `Current data path:` line in `{{context}}`, quoted exactly.

{render_tool_catalogue(diagnostics)}

- `{content['slug']}_catalogue_tool` — list every tool the worker has, with arguments.

## What the worker can do

{choose_table(content, tools)}

## What to do

{numbered(content['decide'])}

## What to produce

Respond with exactly one JSON object and nothing else — no prose around it, no markdown fence:

    {{"approach": "...", "plan": [{{"tool": "...", "arguments": {{}}, "why": "..."}}], "primary_metric": "...", "risks": ["..."], "escalation": null}}

- `approach` — one or two sentences: the method family and why it suits this data.
- `plan` — the worker's tool calls in order. Every `tool` must be one of the tools listed above, spelled exactly;
  `arguments` holds only what you decided (column names, a method, a setting) — the worker fills in the rest.
- `primary_metric` — the one number the worker should judge success by, and why it is the right one here.
- `risks` — what could make a good-looking result wrong (leakage, imbalance, a split that does not match deployment).
- `escalation` — null, or what is missing or wrong and must be resolved before anything runs.

## Rules

{bullets(content['decide_rules'] + DECIDER_RULES)}
"""


DECIDER_RULES = [
    "Decide from what a diagnostic returned, not from what is typical for this kind of problem.",
    "Never name a tool that is not in the lists above. If nothing fits, say so in `escalation`.",
    "Prefer the simplest approach that could work, and make the plan end with a comparison against a baseline.",
    "Output nothing but the JSON object.",
]


def render_yaml(key: str, content: dict, tools: list[ToolInfo], cls_name: str) -> str:
    decider, worker = f"{content['slug']}_decider_agent", f"{content['slug']}_agent"
    catalogue = f"{content['slug']}_catalogue_tool"
    diagnostic_names = [catalogue] + [t.tool_name for t in tools if t.diagnostic]
    all_names = [catalogue] + [t.tool_name for t in tools]

    def listing(names: list[str]) -> str:
        return "\n".join(f'      - "{n}"' for n in names)

    agents = f'''
agents:
  {decider}:  # starts the run — no dependency_agent
    type: "thinker"
    llm: "topic_decider_llm"
    substitute_llm: "topic_worker_llm"
    prompt_path: "decider_prompt.md"
    tools:
{listing(diagnostic_names)}

  {worker}:  # carries out the decider's plan
    type: "generator"
    llm: "topic_worker_llm"
    substitute_llm: "topic_decider_llm"
    prompt_path: "prompt.md"
    dependency_agent: "{decider}"
    tools:
{listing(all_names)}


orchestrators:
  {content['slug']}_workflow:  # sub-agents run in this order; every output is available to the next by name
    sub_agents:
      - "{decider}"
      - "{worker}"


pipeline:
  - name: "{content['slug']}_workflow"
    loops: 1
    description: "{content['title']}: decide the approach, then run it."
    steps:
      - name: "decide"
        processor:
          type: "agent"
          name: "{decider}"
      - name: "solve"
        processor:
          type: "agent"
          name: "{worker}"
'''
    catalogue_description = (
        f"List every tool available for {content['title']} with its description, arguments and optional "
        "dependencies — call it to check whether a tool exists for a step before improvising one."
    )
    return (
        YAML_HEADER.format(title=content["title"], key=key, decider=decider, worker=worker)
        + "\n" + LLMS + "\n"
        + render_tools_yaml(tools, f"{key}.tools.catalogue.tool_catalogue", catalogue_description, catalogue)
        + agents
    )


def outputs(key: str) -> dict[Path, str]:
    content = {**TOPICS[key], "key": key}
    category, name = key.split(".")
    folder = ROOT / category / name
    tools = discover_tools(key)
    cls_name = "".join(part.capitalize() for part in name.split("_"))
    fmt = dict(title=content["title"], key=key, cls=cls_name,
               decider=f"{content['slug']}_decider_agent", worker=f"{content['slug']}_agent")
    return {
        folder / "agentic_configuration.yaml": link_tools(render_yaml(key, content, tools, cls_name), tools),
        folder / "prompt.md": link_tools(render_worker_prompt(content, tools), tools),
        folder / "decider_prompt.md": link_tools(render_decider_prompt(content, tools), tools),
        folder / "decider.py": DECIDER_TEMPLATE.format(**fmt),
        folder / "agents.py": AGENTS_TEMPLATE.format(**fmt),
        folder / "tools" / "catalogue.py": CATALOGUE_TEMPLATE.format(**fmt),
    }


CONSOLE = "console"


def console_output() -> dict[Path, str]:
    """`console/agentic_configurations.yaml`, built from every topic's own generated YAML."""
    from scaffold_console import render_console

    topic_yamls = {key: outputs(key)[ROOT / key.split(".")[0] / key.split(".")[1] / "agentic_configuration.yaml"] for key in TOPICS}
    return {ROOT / "console" / "agentic_configurations.yaml": render_console(topic_yamls)}


def main(argv: list[str]) -> int:
    check = "--check" in argv
    keys = [a for a in argv if not a.startswith("--")] or [*sorted(TOPICS), CONSOLE]
    stale = []
    for key in keys:
        if key != CONSOLE and key not in TOPICS:
            print(f"unknown topic {key!r}; known: {sorted(TOPICS)} and {CONSOLE!r}")
            return 2
        for path, text in (console_output() if key == CONSOLE else outputs(key)).items():
            current = path.read_text() if path.exists() else None
            if current != text:
                stale.append(path)
                if not check:
                    path.parent.mkdir(parents=True, exist_ok=True)
                    path.write_text(text)
        print(f"{key}: {'console config' if key == CONSOLE else str(len(discover_tools(key))) + ' tools'}")
    if check and stale:
        print("stale:\n  " + "\n  ".join(str(p.relative_to(ROOT)) for p in stale))
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
